<?php get_header(); if ( function_exists( 'bigshor_wiki_breadcrumbs' ) ) bigshor_wiki_breadcrumbs(); $term = get_queried_object(); ?>
<header class="bsw-archive-header"><p class="bsw-eyebrow">ENCYCLOPEDIA TOPIC</p><h1 class="page-title"><?php echo esc_html( single_term_title( '', false ) ); ?></h1><?php if ( term_description() ) : ?><div class="subtitle"><?php echo wp_kses_post( term_description() ); ?></div><?php endif; ?><p>Articles filed under this topic in BIGSHOR Wiki.</p></header>
<?php if ( have_posts() ) : ?><ol class="bsw-search-results"><?php while ( have_posts() ) : the_post(); ?><li class="bsw-search-result"><p class="bsw-card-meta">Updated <?php echo esc_html( get_the_modified_date() ); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></li><?php endwhile; ?></ol><nav class="pagination" aria-label="Topic pagination"><?php the_posts_pagination(); ?></nav><?php else : ?><p>No articles are currently assigned to this topic.</p><?php endif; ?><?php get_footer(); ?>